from pathlib import Path
from html import escape
import re
EXTRA={
'services/products/stainless-steel-pipe.html':('چک‌لیست عملیاتی برای خرید و بهره‌برداری لوله استنلس',["در پروژه‌هایی که لوله استنلس برای سیال خورنده استفاده می‌شود، بهتر است پیش از خرید یک جدول انتخاب متریال تهیه شود. این جدول باید غلظت سیال، دما، کلراید، pH، سرعت جریان، امکان رسوب و احتمال شست‌وشوی شیمیایی را کنار گریدهای 304L، 316L، Duplex یا آلیاژهای بالاتر قرار دهد. اگر این مقایسه انجام نشود، ممکن است 316L به اشتباه برای محیطی انتخاب شود که به Duplex یا پوشش داخلی نیاز دارد.","برای انبارداری، لوله استنلس نباید مستقیماً کنار فولاد کربنی یا روی سطح آلوده به براده آهن قرار گیرد. آلودگی آهنی روی سطح استنلس می‌تواند در حضور رطوبت لکه زنگ ایجاد کند و کارفرما تصور کند متریال اشتباه تحویل شده است. استفاده از تسمه، جرثقیل و ابزار تمیز، End Cap مناسب و جداسازی گریدها در انبار برای جلوگیری از آلودگی و اختلاط ضروری است.","در نصب و جوشکاری، Purging داخلی در بسیاری از خطوط استنلس اهمیت دارد. اگر ریشه جوش در سمت داخل اکسید شود، ناحیه Heat Tint می‌تواند مقاومت خوردگی را کاهش دهد. برای همین باید WPS، نوع فیلر، گاز محافظ، تمیزکاری بعد از جوش و در صورت نیاز Passivation در مدارک نصب دیده شود. خرید لوله خوب بدون اجرای درست جوشکاری، نتیجه نهایی قابل قبول ایجاد نمی‌کند.","در TBE پیشنهادها، فقط قیمت هر کیلو یا هر متر را مقایسه نکنید. Seamless یا Welded بودن، کشور ساخت، طول شاخه، تلرانس، Pickling، PMI، نوع بسته‌بندی، زمان تحویل و سطح مدارک روی هزینه واقعی اثر دارد. برای پروژه‌هایی که بازرسی شخص ثالث دارند، بهتر است Hold Point کنترل متریال و PMI قبل از حمل در ITP ثبت شود."]),
'services/products/forged-fittings.html':('چک‌لیست فنی فیتینگ فورج در اجرا و بازرسی',["در اتصالات Socket Weld، رعایت فاصله انبساطی بین انتهای لوله و انتهای Socket اهمیت دارد. اگر لوله تا انتهای Socket فشرده شود و سپس جوشکاری انجام گیرد، انبساط حرارتی می‌تواند تنش اضافی ایجاد کند. این موضوع در خطوط داغ یا سیکل‌دار مهم‌تر است. بنابراین تیم نصب باید قبل از جوشکاری Fit-up را کنترل و ثبت کند.","برای فیتینگ Threaded، نوع رزوه باید دقیق باشد. NPT، BSPT و BSPP قابل جایگزینی تصادفی نیستند. در پروژه‌های نفت و گاز معمولاً NPT رایج است، اما تجهیزات وارداتی یا ابزار دقیق ممکن است رزوه متفاوت داشته باشند. اگر رزوه از ابتدا مشخص نشود، در سایت با نشتی، ترک خوردن اتصال یا نیاز به آداپتورهای غیرمجاز روبه‌رو می‌شوید.","Union در فیتینگ فورج یک قطعه کلیدی برای تعمیرات است. در نقاطی که باز و بست دوره‌ای لازم است، Union می‌تواند دسترسی تعمیراتی را ساده کند؛ اما انتخاب کلاس، متریال و نوع Seat آن باید با سرویس هماهنگ باشد. Union ارزان و بی‌مدرک در سرویس فشار بالا یا خطرناک می‌تواند نقطه ضعف جدی اتصال باشد.","در بازرسی ورودی، ابعاد Socket، عمق، ضخامت، رزوه، Marking، کلاس و متریال باید کنترل شود. برای فیتینگ‌های کوچک، احتمال اختلاط سایز و کلاس در بسته‌بندی زیاد است. تفکیک اقلام بر اساس Tag یا MTO، کنترل تصادفی ابعاد و PMI برای متریال حساس از توقف نصب جلوگیری می‌کند.","اگر برند یا سازنده جایگزین پیشنهاد می‌شود، باید مدارک ASME B16.11، MTC، سابقه ساخت، تست و Marking بررسی شود. در این محصول، ظاهر قطعات بسیار شبیه است و تفاوت اصلی در کیفیت فورج، دقت ماشین‌کاری، ردیابی متریال و کنترل ابعادی دیده می‌شود."]),
'services/products/industrial-power-instrument-cable.html':('راهنمای کاربردی کابل برای طراحی، نصب و نگهداری',["در طراحی کابل، مسیر نصب به اندازه سطح مقطع اهمیت دارد. کابل دفنی، کابل داخل سینی، کابل در کانال بسته، کابل در فضای باز و کابل نزدیک منبع حرارتی هرکدام ضریب تصحیح متفاوت دارند. اگر Derating دما، تجمع کابل‌ها و روش نصب اعمال نشود، کابل در بهره‌برداری گرم می‌شود و عمر عایق کاهش می‌یابد.","برای کابل ابزار دقیق، موضوع اصلی کاهش نویز و حفظ کیفیت سیگنال است. زوج تابیده، شیلد کلی، شیلد زوجی، Drain Wire و نحوه Earthing شیلد باید با فلسفه ابزار دقیق پروژه هماهنگ باشد. اتصال اشتباه شیلد از دو طرف یا قطع آن در مسیر می‌تواند نویز القایی ایجاد کند، مخصوصاً در کنار کابل‌های قدرت و VFD.","در کابل‌های VFD، اثر PWM، dv/dt و جریان‌های Common Mode باید بررسی شود. استفاده از کابل نامناسب یا شیلد/آرمور نادرست می‌تواند باعث نویز، خرابی بیرینگ موتور یا تداخل با ابزار دقیق شود. در مسیرهای طولانی، Reactor یا Sine Filter ممکن است لازم شود و باید با سازنده درایو و موتور هماهنگ گردد.","برای خرید کابل، Drum Length و مدیریت برش اهمیت مالی دارد. اگر طول‌ها بدون بررسی مسیر واقعی سفارش داده شوند، پرت کابل زیاد می‌شود یا در سایت وصله غیرضروری ایجاد می‌گردد. بهتر است Cable Schedule، مسیر کابل و طول رزرو قبل از سفارش نهایی کنترل شود. Drum Number نیز باید در تحویل و نصب ثبت شود تا ردیابی تست و متریال حفظ گردد.","در پروژه‌های دارای الزامات حریق، باید دقیقاً مشخص شود کابل Flame Retardant، Fire Resistant، LSZH یا ترکیبی از این‌هاست. این اصطلاحات معادل نیستند. کابل Fire Resistant باید در آتش برای مدت مشخص عملکرد الکتریکی را حفظ کند، در حالی که LSZH بیشتر به کاهش دود و گاز هالوژنی مربوط است."]),
'services/products/industrial-ups-battery-charger.html':('راهنمای بهره‌برداری و نگهداری UPS صنعتی',["در UPS صنعتی، بارهای متصل باید اولویت‌بندی شوند. همه مصرف‌کننده‌ها نباید بدون تحلیل به UPS وصل شوند. بارهای حیاتی مانند DCS، ESD، F&G، PLC و مخابرات باید از بارهای غیرضروری جدا شوند تا Autonomy واقعی برای تجهیزات حیاتی حفظ شود. اگر بارهای غیرحیاتی به UPS اضافه شوند، زمان پشتیبانی باتری در حادثه واقعی کمتر از انتظار خواهد بود.","باتری ضعیف‌ترین حلقه بسیاری از سیستم‌های UPS است. دمای محیط بالا، شارژ نامناسب، عدم تست دوره‌ای و Aging می‌تواند ظرفیت باتری را به‌شدت کاهش دهد. بنابراین Battery Calculation باید با Aging Factor و Temperature Correction انجام شود و در بهره‌برداری نیز تست دوره‌ای Discharge یا روش‌های مانیتورینگ باتری اجرا گردد.","در سیستم‌های DC Charger، Ripple ولتاژ و کیفیت خروجی برای رله‌ها، Trip Coilها و تجهیزات مخابراتی مهم است. شارژر باید بتواند هم بار DC را تغذیه کند و هم باتری را با پروفایل مناسب شارژ نگه دارد. اگر ظرفیت شارژر فقط بر اساس جریان نامی بار انتخاب شود، زمان شارژ مجدد باتری پس از قطعی طولانی ممکن است بیش از حد شود.","Maintenance Bypass باید با دستورالعمل عملیاتی روشن همراه باشد. وجود بای‌پس بدون Interlock، Labeling و آموزش اپراتور می‌تواند ریسک خطای انسانی ایجاد کند. برای UPSهای حیاتی، Alarmهای باتری، خرابی شارژر، Overload، Bypass Active و دمای محیط باید به DCS یا سیستم مانیتورینگ منتقل شود.","در مقایسه برندهایی مثل Schneider Electric، Eaton، Vertiv، Socomec، ABB یا Riello، فقط kVA را مقایسه نکنید. توپولوژی، راندمان، overload، زمان انتقال، باتری پیشنهادی، قابلیت موازی، SNMP/Modbus، سرویس محلی و موجودی قطعات تعیین می‌کند UPS در بهره‌برداری صنعتی چقدر قابل اعتماد خواهد بود."])
}
for fp,(h,paras) in EXTRA.items():
 p=Path(fp); s=p.read_text(encoding='utf-8',errors='ignore')
 marker='data-extra-phase1="1"'
 if marker in s: continue
 block='<section class="ptf-box" '+marker+'><h2>'+escape(h)+'</h2>'+''.join('<p>'+escape(x)+'</p>' for x in paras)+'</section>'
 idx=s.find('<div class="ptf-cta">')
 if idx!=-1: s=s[:idx]+block+s[idx:]
 p.write_text(s,encoding='utf-8')
 print('extended',fp)
